examples.code:
// If three or more of the player's team's Fighting Spirits are out,
// dismiss the one with the lowest gauge, then summon para_cp0016's Fighting Spirit ck0005.
if (CMND_BTL_GET_AVATER_NUM(0) >= 3)
{
	CMND_BTL_RESET_AVATER(0);
}

CMND_BTL_SET_AVATER("para_cp0016", "ck0005", 0);

// Dismiss one of the team's Fighting Spirits only if three or more are
// out and para_cp0008's is not one of them
if (CMND_BTL_GET_AVATER_NUM(0) >= 3 && !CMND_BTL_HAS_AVATER("para_cp0008"))
{
	CMND_BTL_RESET_AVATER(0);
}

// Arguments in SET_AVATER order: RESET_AVATER reads "ck0001" as the
// player ID, so this call does nothing (see CMND_BTL_RESET_AVATER)
CMND_BTL_RESET_AVATER("para_cp0008", "ck0001", 0);
